/* ===================== BÀI 34 · Baud rate, SCON và SBUF ===================== */
/* Bài 34 · Baud rate, SCON và SBUF (AMTS-EMB-001-M09-L02, MC51-034) — sinh bởi tools/author/mcu8051/l34.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR34=[{"label":"Ví dụ: Gửi \"Hi\" bằng chương trình con PUTC","code":"; Ví dụ 1: UART 9600 baud, gửi \"Hi\" bằng chương trình con\n; Chip: AT89S52, thạch anh 11,0592 MHz.\n        ORG     0000H\n        MOV     TMOD,#20H               ; Timer 1 chế độ 2, tự nạp\n        MOV     TH1,#0FDH               ; 256 - 3: tràn sau mỗi 3 chu kỳ máy\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H               ; 0101 0000B: SM0 SM1 = 01, REN = 1\n        SETB    TR1\n        MOV     A,#'H'\n        ACALL   PUTC\n        MOV     A,#'i'\n        ACALL   PUTC\n        SJMP    $\n; PUTC: gửi A, chờ khung phát xong tới bit STOP\nPUTC:   MOV     SBUF,A\n        JNB     TI,$\n        CLR     TI\n        RET\n        END\n","note":"Bấm Từng bước tới ACALL PUTC: phần Ngăn xếp hiện địa chỉ trở về. Hai khung ‘H’, ‘i’ nối liền nhau vì PUTC chờ TI rồi trở về đủ nhanh để ghi SBUF trước khi bit STOP kết thúc.","dev":{"led":true},"fosc":11059200,"speed":"real"},{"label":"Ví dụ: Nhận 3 byte, gửi lại byte cộng 1","code":"; Ví dụ 2: nhận 3 byte, gửi lại mỗi byte cộng 1 (\"abc\" → \"bcd\")\n; Dữ liệu nhận của ví dụ: \"abc\" đến liền nhau trên RXD.\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H               ; REN = 1: bộ thu chạy\n        SETB    TR1\n        MOV     R7,#3\nLAP:    JNB     RI,$                    ; chờ RI: giữa bit STOP của byte\n        MOV     A,SBUF                  ; đọc SBUF nhận\n        CLR     RI                      ; xóa RI để nhận byte sau\n        INC     A\n        MOV     SBUF,A                  ; ghi SBUF phát: thanh ghi khác!\n        JNB     TI,$\n        CLR     TI\n        DJNZ    R7,LAP\n        SJMP    $\n        END\n","note":"Dữ liệu nhận sẵn “abc”. Mỗi vòng: chờ RI, đọc SBUF (thanh ghi nhận), xóa RI, cộng 1, ghi SBUF (thanh ghi phát). TXD gửi “bcd”. Đoán trước: sau MOV A,SBUF lần đầu, A bằng bao nhiêu? (61H)","dev":{"led":true},"fosc":11059200,"speed":"real","uart":"abc"},{"label":"Ví dụ: SMOD = 1 nhân đôi tốc độ baud","code":"; Ví dụ 3: SMOD = 1 nhân đôi baud: TH1 = FDH cho 19200 baud\n; PCON không định địa chỉ bit: dùng ORL để bật bit 7 (SMOD).\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     TL1,#0FDH\n        ORL     PCON,#80H               ; SMOD = 1\n        MOV     SCON,#50H\n        SETB    TR1\n        MOV     SBUF,#55H\n        JNB     TI,$\n        CLR     TI\n        MOV     SBUF,#55H               ; khung 2: sau khung 1 là 480 CK\n        JNB     TI,$\n        CLR     TI\n        SJMP    $\n        END\n","note":"ORL PCON,#80H bật SMOD: một bit dài 48 chu kỳ máy, khung 480 chu kỳ, tốc độ 19 200 baud với cùng TH1 = FDH. So phần Thời gian với ví dụ 2 của Bài 33.","dev":{"led":true},"fosc":11059200,"speed":"real"},{"label":"Ví dụ: Gửi chuỗi kết thúc 00H từ bộ nhớ CODE","code":"; Ví dụ 4: gửi chuỗi kết thúc bằng 00H đặt trong bộ nhớ CODE\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H\n        SETB    TR1\n        MOV     DPTR,#CHUOI\nGUI:    CLR     A\n        MOVC    A,@A+DPTR               ; đọc ký tự từ CODE\n        JZ      HET                     ; 00H: hết chuỗi\n        MOV     SBUF,A\n        JNB     TI,$\n        CLR     TI\n        INC     DPTR\n        SJMP    GUI\nHET:    SJMP    $\nCHUOI:  DB      'OK',0DH,0AH,0\n        END\n","note":"DPTR trỏ bảng CHUOI trong bộ nhớ CODE. Bốn ký tự ‘O’, ‘K’, CR, LF được gửi liền nhau (3 × 960 + 864 chu kỳ tới TI cuối); khi gặp 00H chương trình dừng, DPTR = 0025H.","dev":{"led":true},"fosc":11059200,"speed":"real"},{"label":"Bẫy: TH1 = FDH với thạch anh 12 MHz","code":"; Bẫy 6: chép nguyên TH1 = FDH sang bo dùng thạch anh 12 MHz\n; Baud = 12 MHz/(384 × 3) ≈ 10 417: lệch +8,5 % so với 9600\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH               ; giá trị của 11,0592 MHz\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H\n        SETB    TR1\n        MOV     SBUF,#'U'\n        JNB     TI,$\n        CLR     TI\n        SJMP    $\n        END\n","note":"Chương trình chạy y hệt ví dụ 1 của Bài 33 (cùng 970 chu kỳ máy) nhưng thạch anh 12 MHz: phần Kết quả ghi baud ≈ 10 417. Máy tính đặt 9600 baud sẽ đọc ra ký tự sai.","dev":{"led":true},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Quên CLR RI, đọc lại cùng một byte","code":"; Bẫy 7: quên CLR RI — đọc hai lần nhưng được cùng một byte\n; Dữ liệu nhận của ví dụ: \"xy\". Muốn 30H = 'x', 31H = 'y'.\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H\n        SETB    TR1\n        JNB     RI,$\n        MOV     30H,SBUF                ; 'x'\n; thiếu CLR RI\n        JNB     RI,$                    ; RI vẫn = 1: không chờ gì cả\n        MOV     31H,SBUF                ; vẫn là 'x'\n        SJMP    $\n        END\n","note":"Dữ liệu nhận sẵn “xy”. Thiếu CLR RI nên lần JNB RI,$ thứ hai đi qua ngay và đọc lại ‘x’: 30H = 31H = 78H, RI vẫn bằng 1, ‘y’ chưa bao giờ được đọc.","dev":{"led":true},"fosc":11059200,"speed":"real","uart":"xy"}];
const sim34=makeSim51(document.getElementById("m51-l34"),{id:"s34",presets:PR34,ram:256});
makeEx51(document.getElementById("ex-l34"),"l34",[{"t":"Khởi tạo 4800 baud","d":"<p>Bo dùng thạch anh 11,0592 MHz. Viết chương trình khởi tạo UART chế độ 1 (8N1, REN = 1) ở <b>4800 baud<\/b> bằng Timer 1 chế độ 2, SMOD = 0, rồi gửi một lần byte ở ô <code>30H<\/code>, chờ phát xong và xóa TI. Trang kiểm tra byte trên TXD và các thanh ghi khi dừng: <code>TMOD = 20H<\/code>, <code>TH1<\/code> đúng cho 4800 baud, <code>SCON = 50H<\/code>, <code>PCON = 00H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 41H<\/code> → TXD gửi “A”.<\/p>","start":"; Bài 1: 4800 baud ở 11,0592 MHz, gửi byte ở 30H\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH               ; đây là giá trị cho 9600 baud\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H\n        SETB    TR1\n; Viết tiếp: gửi byte ở 30H, chờ TI, xóa TI\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":65}},"expect":{"regs":{"TH1":250,"TMOD":32,"SCON":80,"PCON":0},"uart":[65]}},{"setup":{"iram":{"0x30":0}},"expect":{"regs":{"TH1":250,"TMOD":32,"SCON":80,"PCON":0},"uart":[0]}},{"setup":{"iram":{"0x30":255}},"expect":{"regs":{"TH1":250,"TMOD":32,"SCON":80,"PCON":0},"uart":[255]}},{"setup":{"iram":{"0x30":13}},"expect":{"regs":{"TH1":250,"TMOD":32,"SCON":80,"PCON":0},"uart":[13]}},{"setup":{"iram":{"0x30":85}},"expect":{"regs":{"TH1":250,"TMOD":32,"SCON":80,"PCON":0},"uart":[85]}},{"setup":{"iram":{"0x30":128}},"expect":{"regs":{"TH1":250,"TMOD":32,"SCON":80,"PCON":0},"uart":[128]}}],"fosc":11059200},"hints":["Công thức (SMOD = 0): baud = f_osc / (384 × (256 − TH1)). Tính 256 − TH1 = 11 059 200 / (384 × 4800).","256 − TH1 = 6, nên TH1 = 256 − 6 = FAH. Nạp cả TL1 = FAH để lần tràn đầu cũng đúng.","Sau khi gửi xong, cờ TI phải về 0 thì SCON mới đúng giá trị kỳ vọng."],"why":"Mỗi lần giảm một nửa baud thì (256 − TH1) tăng gấp đôi: 9600 → 3, 4800 → 6, 2400 → 12 (F4H), 1200 → 24 (E8H). Quên CLR TI thì SCON = 52H và byte sau sẽ bị gửi khi chưa chờ."},{"t":"Echo chữ hoa tới CR","d":"<p>Ở 9600 baud (đã khởi tạo sẵn trong code mẫu), nhận từng byte qua UART và gửi lại ngay (echo). Chữ thường <code>'a'<\/code>–<code>'z'<\/code> phải gửi lại thành chữ hoa; mọi byte khác gửi lại y nguyên. Sau khi đã gửi lại byte CR (<code>0DH<\/code>) thì dừng ở <code>SJMP $<\/code>, không đọc các byte đến sau CR. Ô <code>30H<\/code> = số byte đã nhận, kể cả CR.<\/p><p>Ví dụ: nhận “hi⏎” (68H 69H 0DH) → gửi “HI⏎”, <code>30H = 03H<\/code>.<\/p>","start":"; Bài 2: gửi lại (echo) từng byte nhận được, chữ thường thành\n; chữ hoa, dừng sau khi đã gửi lại CR (0DH); 30H = số byte nhận\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH               ; 9600 baud\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H\n        SETB    TR1\n        MOV     30H,#0\nLAP:    JNB     RI,$\n        MOV     A,SBUF\n        CLR     RI\n        INC     30H\n; Viết thêm: nếu 'a' <= A <= 'z' thì đổi sang chữ hoa\n        MOV     SBUF,A\n        JNB     TI,$\n        CLR     TI\n        CJNE    A,#0DH,LAP\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"uart":[104,105,13]},"expect":{"uart":"HI\r","iram":{"0x30":3}}},{"setup":{"uart":[13]},"expect":{"uart":"\r","iram":{"0x30":1}}},{"setup":{"uart":[65,122,48,57,13]},"expect":{"uart":"AZ09\r","iram":{"0x30":5}}},{"setup":{"uart":[123,96,125,97,122,13]},"expect":{"uart":"{`}AZ\r","iram":{"0x30":6}}},{"setup":{"uart":[97,98,99,32,120,121,122,13]},"expect":{"uart":"ABC XYZ\r","iram":{"0x30":8}}},{"setup":{"uart":[111,107,13,122,122]},"expect":{"uart":"OK\r","iram":{"0x30":3}}},{"setup":{"uart":[122,64,90,13]},"expect":{"uart":"Z@Z\r","iram":{"0x30":4}}}],"fosc":11059200},"hints":["Code mẫu đã có vòng nhận–gửi đúng. Chỉ cần chèn phần đổi chữ hoa giữa CLR RI và MOV SBUF,A.","So sánh khoảng bằng CJNE A,#hằng,$+3: lệnh không nhảy đi đâu cả nhưng đặt CY = 1 khi A &lt; hằng. Dùng hai lần: với 'a' và với 'z' + 1.","Chữ thường và chữ hoa chỉ khác nhau một bit; chỉ đổi khi ký tự nằm trong khoảng 'a'…'z' (kiểm cả hai biên)."],"why":"Echo trong khi vẫn nhận tiếp được vì UART song công: khung gửi đi và khung nhận về chạy song song, mỗi khung 960 chu kỳ, nên chương trình luôn đọc kịp byte trước khi byte sau nhận xong. Bộ thử 4 bắt lỗi so sánh lệch một ('`' và '{')."},{"t":"Gửi hex trong 56 byte mã","d":"<p>Gửi 4 byte ở <code>30H<\/code>–<code>33H<\/code> thành 8 chữ số hex (chữ hoa, nửa cao trước), rồi CR LF (<code>0DH 0AH<\/code>), ở 9600 baud. Code mẫu đã đúng nhưng mã dài 80 byte. Sửa để mã <b>không quá 56 byte<\/b> (tính cả dữ liệu <code>DB<\/code>). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H..33H = 12 AB 00 FF<\/code> → TXD “12AB00FF⏎” rồi xuống dòng.<\/p>","start":"; Bài 3: gửi 30H–33H thành 8 chữ số hex rồi CR LF. Code này\n; ĐÚNG nhưng dài 80 byte. Sửa để mã không quá 56 byte.\n        ORG     0000H\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     TL1,#0FDH\n        MOV     SCON,#50H\n        SETB    TR1\n        MOV     DPTR,#BANG\n        MOV     R0,#30H\nLAP:    MOV     A,@R0\n        SWAP    A\n        ANL     A,#0FH\n        MOVC    A,@A+DPTR               ; chữ số của nửa cao\n        MOV     SBUF,A\n        JNB     TI,$\n        CLR     TI\n        MOV     A,@R0\n        ANL     A,#0FH\n        MOVC    A,@A+DPTR               ; chữ số của nửa thấp\n        MOV     SBUF,A\n        JNB     TI,$\n        CLR     TI\n        INC     R0\n        CJNE    R0,#34H,LAP\n        MOV     SBUF,#0DH\n        JNB     TI,$\n        CLR     TI\n        MOV     SBUF,#0AH\n        JNB     TI,$\n        CLR     TI\n        SJMP    $\nBANG:   DB      '0123456789ABCDEF'\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":18,"0x31":171,"0x32":0,"0x33":255}},"expect":{"uart":"12AB00FF\r\n"}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0}},"expect":{"uart":"00000000\r\n"}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255}},"expect":{"uart":"FFFFFFFF\r\n"}},{"setup":{"iram":{"0x30":9,"0x31":10,"0x32":144,"0x33":160}},"expect":{"uart":"090A90A0\r\n"}},{"setup":{"iram":{"0x30":1,"0x31":35,"0x32":69,"0x33":103}},"expect":{"uart":"01234567\r\n"}},{"setup":{"iram":{"0x30":137,"0x31":171,"0x32":205,"0x33":239}},"expect":{"uart":"89ABCDEF\r\n"}}],"maxBytes":56,"fosc":11059200},"hints":["Code mẫu lặp lại khối gửi (MOV SBUF, JNB TI, CLR TI) bốn lần. Gom thành một chương trình con PUTC và gọi bằng ACALL (2 byte mỗi lần gọi).","Bảng 16 ký tự tốn 16 byte. Có thể tính chữ số: với n = 0…15, nếu n ≥ 10 thì cộng thêm 7 rồi cộng 30H ('0').","Đổi nửa byte ra ASCII không cần bảng và không cần rẽ nhánh được, nhờ lệnh DA A. Đặt đoạn đổi ngay trước PUTC thì khỏi một lệnh gọi."],"why":"Tối ưu số byte: một chương trình con dùng chung thay cho 4 bản sao, đổi nửa byte sang ASCII bằng phép tính thay cho bảng, và cho HEX “rơi” vào PUTC để khỏi một lệnh gọi. Lời giải tham chiếu 53 byte. Đổi lại chương trình chạy chậm hơn vài chu kỳ mỗi ký tự — không đáng kể so với 960 chu kỳ của một khung."}]);

makeQuiz("quiz34","score34",[{"q": "Thạch anh 11,0592 MHz, SMOD = 0, Timer 1 chế độ 2. TH1 bằng bao nhiêu để có 2400 baud?", "o": ["FAH", "E8H", "F3H", "F4H"], "a": 3, "e": "256 − TH1 = 11 059 200 / (384 × 2400) = 12, nên TH1 = 256 − 12 = F4H. FAH cho 4800, E8H cho 1200; F3H (13) là giá trị cho 2400 baud ở 12 MHz."}, {"q": "Bo dùng thạch anh 12 MHz, TH1 = FDH, SMOD = 0. Máy tính đặt 9600 baud. Điều gì xảy ra?", "o": ["Chạy đúng vì vẫn là 960 chu kỳ máy mỗi khung", "Baud thực ≈ 10 417, lệch +8,5 %: máy tính nhận sai ký tự", "Baud thực ≈ 9 615, lệch 0,16 %: vẫn dùng được", "Không có khung nào được phát"], "a": 1, "e": "12 000 000 / (384 × 3) ≈ 10 417. Số chu kỳ máy mỗi khung không đổi, nhưng mỗi chu kỳ ngắn hơn nên bit ngắn hơn; lệch 8,5 % vượt xa dự trữ khoảng 4 % của khung 8N1."}, {"q": "Lệnh nào bật bit SMOD đúng cách?", "o": ["SETB PCON.7", "MOV PCON,#80H trong mọi trường hợp", "ORL PCON,#80H", "SETB SMOD trong SCON"], "a": 2, "e": "PCON (87H) không định địa chỉ bit nên SETB PCON.7 là lỗi dịch. MOV ghi đè cả các bit khác của PCON; ORL chỉ bật bit 7. SMOD không nằm trong SCON."}, {"q": "Đoạn sau chạy với dữ liệu nhận “xy”: JNB RI,$ · MOV 30H,SBUF · JNB RI,$ · MOV 31H,SBUF (không có CLR RI). Ô 31H bằng gì?", "o": ["79H (‘y’)", "00H", "Chương trình chờ mãi ở lệnh JNB thứ hai", "78H (‘x’)"], "a": 3, "e": "Không xóa RI nên JNB RI,$ thứ hai không chờ, đọc ngay SBUF nhận vẫn còn ‘x’. Byte ‘y’ đến sau khi chương trình đã đọc xong."}, {"q": "Chương trình vừa ghi MOV SBUF,#41H rồi ngay sau đó MOV A,SBUF. A bằng gì?", "o": ["Byte cuối cùng bộ thu đã nhận (không phải 41H)", "41H, vì đọc lại đúng thanh ghi vừa ghi", "Luôn bằng 00H", "Giá trị của TI và RI"], "a": 0, "e": "Địa chỉ 99H là hai thanh ghi: ghi vào thanh ghi phát, đọc từ thanh ghi nhận. Nếu chưa nhận byte nào, A là giá trị còn trong thanh ghi nhận (sau reset thường không xác định trên chip thật)."}]);

fillSnips();
